const unshareFromRule = `-- name: UnshareFromRule :execrows
DELETE FROM space_assets sa WHERE sa.via_rule_id = $1
`

// A rule turned off or narrowed: what it alone shared comes out (by hand stays; nothing is
// excluded, so turning it on again shares them again).
func (q *Queries) UnshareFromRule(ctx context.Context, ruleID uuid.NullUUID) (int64, error) {
	result, err := q.db.Exec(ctx, unshareFromRule, ruleID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const unshareItems = `-- name: UnshareItems :many
WITH gone AS (
    DELETE FROM space_assets sa WHERE sa.space_id = $1 AND sa.asset_id = ANY($2::uuid[])
    RETURNING sa.asset_id
),
kept AS (
    INSERT INTO space_exclusions (space_id, asset_id) SELECT $1, asset_id FROM gone ON CONFLICT DO NOTHING
)
SELECT asset_id FROM gone
`

type UnshareItemsParams struct {
	SpaceID uuid.UUID
	Ids     []uuid.UUID
}

// Out of the space (any member may), and kept out: rules won't put them back.
func (q *Queries) UnshareItems(ctx context.Context, arg UnshareItemsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, unshareItems, arg.SpaceID, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var asset_id uuid.UUID
		if err := rows.Scan(&asset_id); err != nil {
			return nil, err
		}
		items = append(items, asset_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
